package com.cvns.security;import java.util.*;import org.springframework.security.core.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.userdetails.UserDetails;import com.cvns.entities.User;import lombok.*;
@Getter @RequiredArgsConstructor public class CustomUserDetails implements UserDetails{private final User user;public Long getUserId(){return user.getId();}public Collection<? extends GrantedAuthority> getAuthorities(){return List.of(new SimpleGrantedAuthority(user.getUserRole().name()));}public String getPassword(){return user.getPassword();}public String getUsername(){return user.getEmail();}public boolean isEnabled(){return user.isActive();}}
